 folders:@js($folders),current:@js($selected?->id),view:@js($selected || request()->boolean('unfiled') ? 'items':'folders'),currentFolder:@js($selected ? ['id'=>$selected->id,'name'=>$selected->name,'url'=>route('user.projects.show',$selected)] : null),items:[],kinds:['link'],linkTypesSelected:[],draftKinds:['link'],draftLinkTypes:[],draftSort:'name',sort:'name',filtersOpen:false,search:'',selected:[],destination:'',loading:false,busy:false,moving:[],dragKeys:[],hover:'',opening:null,notice:'',error:false,undoMove:null,newName:'',newColor:'#8b5cf6',createError:'',page:1,total:0,hasMore:false,requestId:0,list:false,
