 get visibleFolders(){return this.folders.filter(f=>f.name.toLowerCase().includes(this.search.toLowerCase()));},
 icon(kind){return 'fas '+({link:'fa-link',form:'fa-list',qr:'fa-qrcode',file:'fa-file',calendar:'fa-calendar',board:'fa-columns',task:'fa-check',plan:'fa-clipboard-list',mind:'fa-brain',staff:'fa-robot',project:'fa-folder',campaign:'fa-bullhorn',brand:'fa-palette',budget:'fa-chart-line'}[kind]||'fa-cube');},
 itemVisual(item){const type=item.kind==='link'?this.linkCatalog[item.link_type]:null;if(type)return{icon:'fas '+type.icon,color:type.tint||'#8b5cf6',label:type.label};const colors={link:'#8b5cf6',file:'#64748b',form:'#0d9488',qr:'#7c3aed',calendar:'#ea580c',board:'#2563eb',task:'#16a34a',plan:'#0891b2',mind:'#9333ea',staff:'#0d9488',project:'#d97706',campaign:'#db2777',brand:'#c026d3',budget:'#059669'};if(item.kind==='file'){const ext=(item.name||'').split('.').pop().toLowerCase();const fileTypes=[[/^(png|jpe?g|gif|webp|svg|avif|heic)$/,'fa-file-image','#16a34a','Image'],[/^(mp4|webm|mov|avi|mkv)$/,'fa-file-video','#7c3aed','Video'],[/^(mp3|wav|ogg|m4a|flac)$/,'fa-file-audio','#db2777','Audio'],[/^pdf$/,'fa-file-pdf','#dc2626','PDF'],[/^(xlsx?|csv|ods)$/,'fa-file-excel','#059669','Spreadsheet'],[/^(docx?|odt|txt|md)$/,'fa-file-alt','#2563eb','Document'],[/^(zip|rar|7z|tar|gz)$/,'fa-file-archive','#d97706','Archive']];const match=fileTypes.find(t=>t[0].test(ext));if(match)return{icon:'fas '+match[1],color:match[2],label:match[3]};}return{icon:this.icon(item.kind),color:colors[item.kind]||'#64748b',label:this.labels[item.kind]||item.kind};},
 iconStyle(item){const c=this.itemVisual(item).color;return 'color:'+c+';background:color-mix(in srgb,'+c+' 13%,var(--bg-card))';},
 async api(url,body){const r=await fetch(url,{method:body?'POST':'GET',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},...(body?{body:JSON.stringify(body)}:{})});if(!r.headers.get('content-type')?.includes('application/json'))throw Error('Your session changed. Refresh this page and sign in again.');const data=await r.json();if(!r.ok)throw Error(Object.values(data.errors||{}).flat()[0]||data.message||'The action could not be completed.');return data;},
 url(){const u=new URL(@js(route('user.folders.index')));if(this.view==='items'){if(this.current)u.searchParams.set('folder',this.current);else u.searchParams.set('unfiled','1');}return u;},
 async openFolder(id){if(this.busy||this.opening!==null)return;this.opening=id;this.search='';this.selected=[];this.destination='';if(id&&!matchMedia('(prefers-reduced-motion: reduce)').matches)await new Promise(r=>setTimeout(r,150));this.current=id;this.currentFolder=this.folders.find(f=>f.id===id)||null;this.view='items';this.opening=null;history.pushState({},'',this.url());await this.load();},
 back(){if(this.busy)return;this.requestId++;this.view='folders';this.current=null;this.currentFolder=null;this.items=[];this.selected=[];this.search='';this.loading=false;history.pushState({},'',this.url());},
 restore(){const u=new URL(location.href);this.current=Number(u.searchParams.get('folder'))||null;this.view=this.current||u.searchParams.has('unfiled')?'items':'folders';this.search='';this.selected=[];this.currentFolder=this.folders.find(f=>f.id===this.current)||null;if(this.view==='items')this.load();else{this.requestId++;this.loading=false;}},
 async load(more=false){const token=++this.requestId;this.loading=true;if(!more)this.selected=[];const page=more?this.page+1:1;const u=new URL(@js(route('user.folders.contents')));if(this.current)u.searchParams.set('folder',this.current);u.searchParams.set('q',this.search);this.kinds.forEach(k=>u.searchParams.append('kind[]',k));this.linkTypesSelected.forEach(k=>u.searchParams.append('link_type[]',k));u.searchParams.set('sort',this.sort);u.searchParams.set('page',page);try{const data=await this.api(u);if(token!==this.requestId)return;this.items=more?[...this.items,...data.items]:data.items;this.currentFolder=data.folder;this.folders=data.folders;this.total=data.total;this.page=data.page;this.hasMore=data.has_more;}catch(e){if(token===this.requestId){this.notice=e.message;this.error=true;}}finally{if(token===this.requestId)this.loading=false;}},
 toggle(item){if(!item.movable||this.busy)return;this.selected=this.selected.includes(item.key)?this.selected.filter(k=>k!==item.key):[...this.selected,item.key];},
 selectAll(){this.selected=this.items.filter(i=>i.movable).slice(0,50).map(i=>i.key);},
 startDrag(e,item){if(!item.movable||this.busy){e.preventDefault();return;}this.dragKeys=this.selected.includes(item.key)?[...this.selected]:[item.key];e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',this.dragKeys.join(','));},
 drop(id){if(id&&!this.folders.find(f=>f.id===id)?.writable){this.notice='You can view that folder, but cannot move items into it.';this.error=true;this.hover='';return;}const keys=[...this.dragKeys];this.hover='';if(keys.length)this.move(keys,id);},
 async move(keys,target,undoing=false){if(this.busy||!keys.length||target===this.current)return;if(keys.length>50){this.notice='Select up to 50 items for one move.';this.error=true;return;}const source=this.current;this.busy=true;this.moving=[...keys];this.error=false;try{await this.api(@js(route('user.folders.items.move')),{items:keys,source,destination:target});this.notice=keys.length+' item'+(keys.length===1?'':'s')+' moved '+(target?'to '+(this.folders.find(f=>f.id===target)?.name||'folder'):'out to Unfiled items')+'.';this.undoMove=undoing?null:{keys:[...keys],source,target};this.destination='';await this.load();}catch(e){this.notice=e.message;this.error=true;}finally{this.busy=false;this.moving=[];this.dragKeys=[];}},
 async undo(){const m=this.undoMove;if(!m||this.busy)return;this.busy=true;try{await this.api(@js(route('user.folders.items.move')),{items:m.keys,source:m.target,destination:m.source});this.undoMove=null;this.notice='Move undone.';this.error=false;await this.load();}catch(e){this.notice=e.message;this.error=true;}finally{this.busy=false;}},
 applyFilters(){this.kinds=[...this.draftKinds];this.linkTypesSelected=[...this.draftLinkTypes];if(this.linkTypesSelected.length&&!this.kinds.length)this.kinds=['link'];this.draftKinds=[...this.kinds];this.sort=this.draftSort;this.$el.querySelectorAll('details[open]').forEach(d=>d.open=false);if(this.view==='items')this.load();},
 resetFilters(){this.kinds=['link'];this.linkTypesSelected=[];this.draftKinds=['link'];this.draftLinkTypes=[];this.sort='name';this.draftSort='name';if(this.view==='items')this.load();},
 async folderCreated(folder){this.folders=[...this.folders.filter(f=>f.id!==folder.id),{...folder,writable:true}].sort((a,b)=>a.name.localeCompare(b.name));await this.openFolder(folder.id);}

};}
</script>
@endsection
